    public const ACTIONS=['task.save','task.book','task.move','task.schedule','task.archive','task.restore','task.complete','task.dependencies','checklist.toggle','goal.save','goal.archive','goal.restore','list.save','list.move','list.archive','list.restore','board.save','board.archive','board.restore','sprint.save','note.save','note.archive','note.restore','map.save','map.archive','map.connect','map.disconnect','routine.save','routine.toggle','review.save','quarter.review','memory.save','memory.remove','map.create','tracker.save','tracker.archive','tracker.restore','category.save','category.archive','category.restore','opportunity.save','opportunity.applied','opportunity.archive','opportunity.restore'];
    public static function schema():array {return ['type'=>'OBJECT','required'=>['authorization','actions'],'properties'=>['authorization'=>['type'=>'STRING','description'=>'An exact quote of the CURRENT user instruction authorizing changes. Empty for discussion.'],'actions'=>['type'=>'ARRAY','items'=>['type'=>'OBJECT','required'=>['operation','arguments'],'properties'=>['operation'=>['type'=>'STRING','enum'=>self::ACTIONS],'arguments'=>['type'=>'STRING','description'=>'JSON object of arguments. Use exact existing IDs. For task.save/goal.save/note.save/map.save send only changed fields. Omit id to create.']]]]]];}
    public static function explicit(string $message,string $quote):bool {
        if($quote==='')return false;$normalize=fn($text)=>trim(preg_replace('/[^\pL\pN]+/u',' ',mb_strtolower($text)));if(!str_contains(' '.$normalize($message).' ',' '.$normalize($quote).' '))return false;
        // Conservative: exploratory, conditional and negative instructions stay discussion.
        if(preg_match('/\b(don[’\x{0027}]?t|do not|never|not yet|without|instead of|if|could|would|should|maybe|might|thinking|consider|suggest|propose|example|imagine|hypothetical)\b/iu',$message))return false;
        return (bool)preg_match('/^(?:(?:hi|hello|hey|just|okay|ok|yes|now|then|and|also|please|go ahead)[,\s.!:]*)*(?:(?:can|will) you\s+(?:help me\s+)?|I (?:want|need)(?: you)? to\s+|I[’\x{0027}]d like(?: you)? to\s+)?(?:please\s+)?(add|create|make|put|book|plan|arrange|move|rename|change|update|edit|set|schedule|reschedule|remind|link|archive|remove|restore|save|remember|forget|mark|complete|organize|turn|convert|connect|disconnect|undo)\b/iu',trim($quote));
    }
    public static function context(array $s):array {
        $index=[];foreach(['boards','lists','goals','tasks','notes','mapNodes','routines'] as $type){$rows=$s[$type]??[];$index[$type]=array_map(function($r){return array_intersect_key($r,array_flip(['id','title','name','archived','boardId','listId','goalId','parentId','type','period','completed','dueDate','dueTime','reminderMinutes','schedule','group','kind','nextDate','priority','blocker','checklist']));},array_slice($rows,0,500));$index['counts'][$type]=count($rows);}
        $index['sprints']=$s['sprints']??[];$index['quarterReviews']=array_slice($s['quarterReviews']??[],-2,null,true);$index['week']=LifeStore::week();$index['date']=(new DateTimeImmutable('now',new DateTimeZone(LifeStore::$timezone)))->format('Y-m-d');return $index;
    }
    public static function confirmation(array $actions,array $board):string {
        $messages=[];$today=(new DateTimeImmutable('now',new DateTimeZone(LifeStore::$timezone)))->format('Y-m-d');$tomorrow=(new DateTimeImmutable('tomorrow',new DateTimeZone(LifeStore::$timezone)))->format('Y-m-d');
        foreach($actions as $action){$op=$action['operation'];$a=$action['arguments']??[];if(is_string($a))$a=json_decode($a,true)??[];$title=$a['title']??$a['name']??'';
            $type=match(explode('.',$op)[0]){'goal'=>'goals','task','checklist'=>'tasks','board'=>'boards','list'=>'lists','note'=>'notes','routine'=>'routines','map'=>'mapNodes',default=>null};if($type&&isset($a['id']))foreach($board[$type]??[] as $row)if($row['id']===$a['id'])$title=$row['title']??$row['name']??'';
            $name=$title!==''?'“'.$title.'”':'the item';$verb=match($op){'task.save','goal.save','board.save','list.save','note.save','routine.save'=>empty($a['id'])?'Added':'Updated','task.book'=>'Booked','task.move'=>'Moved','task.schedule'=>'Scheduled','checklist.toggle'=>($a['done']??false)?'Checked an item on':'Unchecked an item on','task.complete'=>($a['done']??false)?'Completed':'Reopened','task.archive','goal.archive','board.archive','list.archive','note.archive','map.archive'=>'Archived','task.restore','goal.restore','board.restore','list.restore','note.restore'=>'Restored','map.create'=>'Created mind map',default=>'Saved'};
            $text=$verb.' '.($op==='goal.save'?'goal ':'').$name;
            if($op==='task.move')foreach($board['lists'] as $l)if($l['id']===($a['listId']??''))$text.=' to '.$l['name'];
            if(!empty($a['dueDate']))$text.=' for '.($a['dueDate']===$today?'today':($a['dueDate']===$tomorrow?'tomorrow':$a['dueDate']));
            if(in_array($op,['task.schedule','task.book'],true)&&!empty($a['date']))$text.=' for '.($a['date']===$today?'today':($a['date']===$tomorrow?'tomorrow':$a['date'])).(!empty($a['time'])?' at '.$a['time']:'');if($op==='task.book')$text.=' in your Life calendar ('.$a['minutes'].' minutes)';if($op==='goal.save'&&!empty($a['period']))$text.=' for '.$a['period'];$messages[]=$text.'.';
        }return implode(' ',array_slice($messages,0,20));
    }
    public static function relevant(array $s,string $query,array $screen=[]):array {
        $selected=[];array_walk_recursive($screen,function($v)use(&$selected){if(is_string($v))$selected[]=$v;});
        $words=preg_split('/[^\pL\pN]+/u',mb_strtolower($query));$words=array_filter($words,fn($w)=>mb_strlen($w)>2);
        $out=self::context($s);foreach(['tasks','goals','notes','mapNodes','routines'] as $type){
            $scored=[];foreach($s[$type]??[] as $row){$title=mb_strtolower(($row['title']??$row['name']??'').' '.($row['notes']??''));$score=in_array($row['id']??'', $selected,true)?1000:0;foreach($words as $w)if(str_contains($title,$w))$score+=10;
                if($type==='goals'&&!($row['archived']??false)&&!($row['completed']??false))$score+=2;
                if($score>0)$scored[]=['score'=>$score,'row'=>$row];}
            usort($scored,fn($a,$b)=>$b['score']<=>$a['score']);$out[$type]=array_map(fn($r)=>array_intersect_key($r['row'],array_flip(['id','title','name','archived','boardId','listId','goalId','parentId','type','period','completed','dueDate','dueTime','reminderMinutes','schedule','group','kind','priority','blocker','checklist'])),array_slice($scored,0,32));
        }
        $week=LifeStore::week();$out['sprints']=[$week=>$s['sprints'][$week]??['goal'=>'','taskIds'=>[]]];return $out;
    }
    public static function execute(LifeStore $store,LifeAI $ai,int $version,int $boardVersion,string $message,array $plan,string $requestId,?string $voiceSessionId=null,bool $nativeIntent=false,bool $chatIntent=false,?LifeChatAttachments $chatFiles=null,array $attachmentIds=[],string $conversationId=''):array {
