        $applicationOps=array_values(array_filter($actions,fn($a)=>preg_match('/^(tracker|category|opportunity)\./',$a['operation']??'')));$apps=null;$beforeApps=null;$appConfirmations=[];if($applicationOps){require_once __DIR__.'/applications.php';$apps=new LifeApplications($store);$beforeApps=$apps->read();if(isset($plan['_applicationsVersion'])&&$beforeApps['version']!==$plan['_applicationsVersion'])throw new LifeError('Applications changed while I was thinking. No changes were made; refresh the context.',409);}
