              $previous=$board['state'];$create=['title'=>$args['title'],'listId'=>$args['listId']];$board=$store->mutate($board['version'],'task.save',$create);self::verifyTaskMutation('task.save',$create,$previous,$store->read()['state']);
              $ids=array_values(array_diff(array_column($board['state']['tasks'],'id'),array_column($previous['tasks'],'id')));$id=$ids[0];$schedule=['id'=>$id,'date'=>$args['date'],'time'=>$args['time'],'minutes'=>$args['minutes']];$previous=$board['state'];$board=$store->mutate($board['version'],'task.schedule',$schedule);$persisted=$store->read();self::verifyTaskMutation('task.schedule',$schedule,$previous,$persisted['state']);
