        $state['commands'][]=$receipt;$state['commands']=array_slice($state['commands'],-10);$updated=$ai->write($r['version'],$state);require_once __DIR__.'/google-sync.php';LifeGoogleSync::enqueue($store);$db->commit();unset($receipt['before'],$receipt['beforeMemories'],$receipt['beforeApplications']);return $updated+['board'=>$board,'receipt'=>$receipt];
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($chatFiles)$chatFiles->cleanupCopies();throw $e;}
    }
    /** Verify requested task effects against a fresh persisted state before issuing a receipt. */
    public static function verifyTaskMutation(string $op,array $args,array $before,array $after):void {
        if(!str_starts_with($op,'task.')&&$op!=='checklist.toggle')return;
        $id=$args['id']??'';$rows=$after['tasks']??[];
        if($op==='task.save'&&$id===''){$oldIds=array_column($before['tasks']??[],'id');$created=array_values(array_filter($rows,fn($t)=>!in_array($t['id'],$oldIds,true)));if(count($created)!==1)throw new LifeError('The task creation could not be verified. No changes were saved.',409);$id=$created[0]['id'];}
        $task=null;foreach($rows as $row)if($row['id']===$id)$task=$row;if(!$task)throw new LifeError('The saved task could not be read back. No changes were saved.',409);
        $fail=static function(){throw new LifeError('The saved task does not match the requested change. No changes were saved.',409);};
        if($op==='task.save'){
            foreach(['title','notes','blocker','listId','priority','dueDate','dueTime','reminderMinutes','color','goalId','effortMinutes'] as $key){if(!array_key_exists($key,$args))continue;$expected=is_string($args[$key])?trim($args[$key]):$args[$key];if(($args['dueDate']??null)===''&&$key==='dueTime')$expected='';if(($args['dueDate']??null)===''&&$key==='reminderMinutes')$expected=null;if(($task[$key]??null)!==$expected)$fail();}
            if(isset($args['checklist'])){$expected=array_map(fn($i)=>['text'=>trim($i['text']),'done'=>($i['done']??false)===true],$args['checklist']);$actual=array_map(fn($i)=>['text'=>$i['text'],'done'=>$i['done']],$task['checklist']);if($actual!==$expected)$fail();}
            if(isset($args['labels'])&&$task['labels']!==array_values(array_unique(array_map('trim',$args['labels']))))$fail();
        }elseif($op==='task.move'){if($task['listId']!==$args['listId'])$fail();}
        elseif($op==='task.complete'){$list=null;foreach($after['lists'] as $row)if($row['id']===$task['listId'])$list=$row;if(!$list||$list['isDone']!==$args['done']||(bool)($task['completedAt']??false)!==$args['done'])$fail();}
        elseif($op==='task.archive'||$op==='task.restore'){if($task['archived']!==($op==='task.archive'))$fail();if($op==='task.restore'&&!empty($args['listId'])&&$task['listId']!==$args['listId'])$fail();}
        elseif($op==='task.schedule'){$expected=($args['date']??'')===''?null:['date'=>$args['date'],'time'=>$args['time'],'minutes'=>$args['minutes']??60];if(($task['schedule']??null)!==$expected)$fail();}
        elseif($op==='task.dependencies'){if(($task['dependencies']??[])!==array_values(array_unique($args['ids']??[])))$fail();}
        elseif($op==='checklist.toggle'){$item=null;foreach($task['checklist'] as $row)if($row['id']===$args['itemId'])$item=$row;if(!$item||$item['done']!==$args['done'])$fail();}
    }
    public static function undo(LifeStore $store,LifeAI $ai,int $version,string $id,?array $nativeContext=null):array {
        require_once __DIR__.'/applications.php';$apps=new LifeApplications($store);$apps->read();$db=$store->db;$db->beginTransaction();try{$r=$ai->read();if($r['version']!==$version)throw new LifeError('Reload Ramble before undoing.',409);$s=$r['state'];$i=null;foreach($s['commands']??[] as $n=>$c)if($c['id']===$id)$i=$n;if($i===null||$s['commands'][$i]['undone'])throw new LifeError('This change cannot be undone.',409);$c=&$s['commands'][$i];$board=$store->read();if($board['version']!==$c['afterVersion'])throw new LifeError('Other work was saved after this command. Ask for a specific correction instead.',409);
        if(isset($c['beforeApplications'])){$appCurrent=$apps->read();if($appCurrent['version']!==$c['afterApplicationsVersion'])throw new LifeError('Applications changed after this command. Ask for a specific correction.',409);$q=$db->prepare('UPDATE life_applications SET state=?,version=version+1,updated_at=? WHERE id=? AND version=?');$q->execute([json_encode($c['beforeApplications'],JSON_THROW_ON_ERROR),LifeStore::now(),$store->tenantId,$appCurrent['version']]);if($q->rowCount()!==1)throw new LifeError('Applications changed before undo.',409);}
        // Memory corrections must also survive undo of an older command.
        if(array_filter($c['operations'],fn($op)=>str_starts_with($op,'memory.'))){$after=$c['afterMemories']??null;if($after===null||$s['memories']!==$after)throw new LifeError('Memory changed after this command. Ask for a specific correction.',409);$s['memories']=$c['beforeMemories'];$s['memoryEpoch']=($s['memoryEpoch']??0)+1;foreach($s['conversations'] as &$chat)$chat['summary']='';unset($chat);}
        $q=$db->prepare('UPDATE life_board SET state=?,version=version+1,updated_at=? WHERE id=? AND version=?');$q->execute([json_encode($c['before'],JSON_THROW_ON_ERROR),LifeStore::now(),$store->tenantId,$board['version']]);if($q->rowCount()!==1)throw new LifeError('Your planner changed before undo.',409);$store->history->capture($board['state'],$c['before'],'undo',$board['version']+1);$c['undone']=true;unset($c);$receipt=null;if($nativeContext){$receipt=['id'=>'undo-'.LifeStore::id(),'summary'=>'Undid the last saved change.','entities'=>[],'operations'=>['undo'],'voiceSessionId'=>$nativeContext['sessionId'],'undone'=>false];foreach($s['voiceSessions'] as &$session)if($session['id']===$nativeContext['sessionId'])$session['nativeCommands'][$nativeContext['requestId']]=['turnId'=>$nativeContext['turnId'],'receipt'=>$receipt];unset($session);}$updated=$ai->write($version,$s);require_once __DIR__.'/google-sync.php';LifeGoogleSync::enqueue($store);$db->commit();return $updated+['board'=>$store->read()]+($receipt?['receipt'=>$receipt]:[]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
    }
